const payload = {
                barcodeValue: this.form.barcodeValue,
                barcodeFormat: this.form.barcodeFormat,
                title: this.form.title,
                colorPreset: this.form.colorPreset,
              };

              if (this.form.label && this.form.value) {
                payload.label = this.form.label;
                payload.value = this.form.value;
              }

              const apiUrl =
                window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'
                  ? 'http://localhost:8787/api/pkpass'
                  : 'https://wallet-pass-api.workers2000.workers.dev/api/pkpass';

              const response = await fetch(apiUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
              });
